import torch
import triton
import triton.language as tl
from task import input_t, output_t


# =============================================================================
# Persistent one-threadblock-per-matrix fused Householder QR megakernel.
#
# Two backends:
#  * Triton unblocked tile kernel for tiny n (<= 64): whole matrix in registers.
#  * CUDA full-matrix-in-smem kernel for small/medium n that fits 227KB smem:
#    one thread block factors one matrix entirely on-chip (read once, write
#    once). Thread `t` owns column `t` (column-major smem), so the trailing
#    Householder update A[:,j] -= tau*v*(v.A[:,j]) is a per-thread sequential
#    dot product with no cross-thread reduction; only the pivot column norm
#    needs a block reduction. Output is packed LAPACK/geqrf layout:
#       H = R on/above diag, reflectors v (v[k]=1 implicit) below; tau[k] coef.
#    Q = householder_product(H, tau), R = triu(H): matches torch.geqrf.
# =============================================================================


# ----------------------------- Triton (tiny n) -------------------------------
@triton.jit
def _qr_unblocked_kernel(
    A_ptr, TAU_ptr, B,
    N: tl.constexpr, BN: tl.constexpr,
):
    pid = tl.program_id(0)
    num_programs = tl.num_programs(0)
    row = tl.arange(0, BN)
    col = tl.arange(0, BN)
    valid_r = row < N
    valid_c = col < N
    mask2d = valid_r[:, None] & valid_c[None, :]
    b = pid
    while b < B:
        base = b * N * N
        a = tl.load(A_ptr + base + row[:, None] * N + col[None, :],
                    mask=mask2d, other=0.0)
        for k in range(0, N - 1):
            ak = tl.sum(tl.where(col[None, :] == k, a, 0.0), axis=1)
            below = row >= k
            xk = tl.where(below, ak, 0.0)
            alpha = tl.sum(tl.where(row == k, ak, 0.0))
            normsq = tl.sum(xk * xk)
            xnorm = tl.sqrt(normsq)
            sign = tl.where(alpha >= 0.0, 1.0, -1.0)
            beta = -sign * xnorm
            safe = xnorm > 0.0
            tau = tl.where(safe, (beta - alpha) / beta, 0.0)
            denom = alpha - beta
            inv_denom = tl.where(safe & (denom != 0.0), 1.0 / denom, 0.0)
            v = xk * inv_denom
            v = tl.where(row == k, 1.0, v)
            v = tl.where(below, v, 0.0)
            w = tl.sum(v[:, None] * a, axis=0)
            colmask = col >= k
            a = tl.where(colmask[None, :], a - tau * (v[:, None] * w[None, :]), a)
            colk_sel = col[None, :] == k
            new_colk = tl.where(row[:, None] == k, beta,
                                tl.where(row[:, None] > k, v[:, None], a))
            a = tl.where(colk_sel, new_colk, a)
            tl.store(TAU_ptr + b * N + k, tau)
        tl.store(TAU_ptr + b * N + (N - 1), 0.0)
        tl.store(A_ptr + base + row[:, None] * N + col[None, :], a, mask=mask2d)
        b += num_programs


def _qr_triton(a: torch.Tensor) -> output_t:
    B, n, _ = a.shape
    H = a.clone()
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    BN = triton.next_power_of_2(n)
    num_sms = torch.cuda.get_device_properties(a.device).multi_processor_count
    grid = (min(num_sms, B),)
    _qr_unblocked_kernel[grid](H, tau, B, N=n, BN=BN)
    return H, tau


# --------------------------- CUDA full-in-smem -------------------------------
_CUDA_SRC = r"""
#include <cstdint>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// One thread block per matrix. The full n x n matrix is held in shared memory
// (column-major: As[r + c*n]). Thread t owns column t (and t + blockDim, ...).
// Right-looking unblocked Householder; writes packed (H, tau).
//
// Templated thread count TPB; n passed at runtime (n <= TPB or strided).
template <int TPB>
__global__ void qr_smem_kernel(const float* __restrict__ A,
                               float* __restrict__ H,
                               float* __restrict__ tau,
                               int B, int n) {
    extern __shared__ float smem[];
    float* As = smem;             // n*n floats
    float* red = smem + n * n;    // TPB floats for reductions
    float* vcol = red + TPB;      // n floats: current reflector v (rows)
    float* sval = vcol + n;       // small scalars: [0]=beta,[1]=tau,[2]=invdenom

    const int tid = threadIdx.x;

    for (int b = blockIdx.x; b < B; b += gridDim.x) {
        const float* Ab = A + (size_t)b * n * n;   // row-major input (b,r,c)
        float* Hb = H + (size_t)b * n * n;
        float* taub = tau + (size_t)b * n;

        // Load matrix into smem, transposing row-major -> column-major.
        // input element (r,c) at Ab[r*n + c] -> As[r + c*n].
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            As[c * n + r] = Ab[r * n + c];
        }
        __syncthreads();

        for (int k = 0; k < n - 1; ++k) {
            // --- pivot column norm over rows >= k ---
            float partial = 0.f;
            for (int r = k + tid; r < n; r += TPB) {
                float x = As[k * n + r];
                partial += x * x;
            }
            red[tid] = partial;
            __syncthreads();
            for (int s = TPB / 2; s > 0; s >>= 1) {
                if (tid < s) red[tid] += red[tid + s];
                __syncthreads();
            }
            // thread 0 computes beta/tau/invdenom
            if (tid == 0) {
                float normsq = red[0];
                float xnorm = sqrtf(normsq);
                float alpha = As[k * n + k];
                float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                float tval, invden;
                if (xnorm > 0.f && (alpha - beta) != 0.f) {
                    tval = (beta - alpha) / beta;
                    invden = 1.f / (alpha - beta);
                } else {
                    tval = 0.f;
                    invden = 0.f;
                    beta = alpha;  // no reflection
                }
                sval[0] = beta;
                sval[1] = tval;
                sval[2] = invden;
            }
            __syncthreads();
            float beta = sval[0];
            float tval = sval[1];
            float invden = sval[2];

            // build v into vcol: v[k]=1, v[r]=As[k,r]*invden for r>k, else 0
            for (int r = tid; r < n; r += TPB) {
                float vv;
                if (r < k) vv = 0.f;
                else if (r == k) vv = 1.f;
                else vv = As[k * n + r] * invden;
                vcol[r] = vv;
            }
            __syncthreads();

            // trailing update: each thread owns columns j (strided), j > k
            for (int j = k + 1 + tid; j < n; j += TPB) {
                float* Acol = As + j * n;
                // w = v . A[:,j]  over rows >= k
                float w = 0.f;
                #pragma unroll 4
                for (int r = k; r < n; ++r) w += vcol[r] * Acol[r];
                float tw = tval * w;
                #pragma unroll 4
                for (int r = k; r < n; ++r) Acol[r] -= tw * vcol[r];
            }
            __syncthreads();

            // pack column k: diag = beta, below = v ; tau[k] = tval
            for (int r = tid; r < n; r += TPB) {
                if (r == k) As[k * n + r] = beta;
                else if (r > k) As[k * n + r] = vcol[r];
            }
            if (tid == 0) taub[k] = tval;
            __syncthreads();
        }
        if (tid == 0) taub[n - 1] = 0.f;
        __syncthreads();

        // write H back row-major: Hb[r*n+c] = As[c*n+r]
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            Hb[r * n + c] = As[c * n + r];
        }
        __syncthreads();
    }
}

void qr_smem_launch(int64_t A_ptr, int64_t H_ptr, int64_t tau_ptr,
                    int B, int n, int grid) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    size_t shbytes = ((size_t)n * n + TPB + n + 4) * sizeof(float);
    cudaFuncSetAttribute(qr_smem_kernel<TPB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)shbytes);
    qr_smem_kernel<TPB><<<grid, TPB, shbytes>>>(A, H, tau, B, n);
}

// ---------------------------------------------------------------------------
// Global-memory unblocked Householder, one block per matrix. Matrix held in a
// COLUMN-MAJOR global scratch (Acm[b*n*n + c*n + r]); only the current
// reflector and reductions live in smem. BLAS-2 trailing update over global
// columns, but the whole batch is processed in parallel (grid blocks looping
// over matrices). For n that does not fit fully in smem (n > ~224).
template <int TPB>
__global__ void qr_global_kernel(const float* __restrict__ A,  // row-major in
                                 float* __restrict__ Acm,      // col-major scratch
                                 float* __restrict__ H,        // row-major out
                                 float* __restrict__ tau,
                                 int B, int n) {
    extern __shared__ float smem[];
    float* red = smem;            // TPB
    float* vcol = red + TPB;      // n: reflector v (rows)
    float* sval = vcol + n;       // scalars

    const int tid = threadIdx.x;

    for (int b = blockIdx.x; b < B; b += gridDim.x) {
        const float* Ab = A + (size_t)b * n * n;
        float* Acmb = Acm + (size_t)b * n * n;
        float* Hb = H + (size_t)b * n * n;
        float* taub = tau + (size_t)b * n;

        // transpose row-major -> column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            Acmb[c * n + r] = Ab[r * n + c];
        }
        __syncthreads();

        for (int k = 0; k < n - 1; ++k) {
            float* colk = Acmb + (size_t)k * n;
            float partial = 0.f;
            for (int r = k + tid; r < n; r += TPB) {
                float x = colk[r];
                partial += x * x;
            }
            red[tid] = partial;
            __syncthreads();
            for (int s = TPB / 2; s > 0; s >>= 1) {
                if (tid < s) red[tid] += red[tid + s];
                __syncthreads();
            }
            if (tid == 0) {
                float xnorm = sqrtf(red[0]);
                float alpha = colk[k];
                float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                float tval, invden;
                if (xnorm > 0.f && (alpha - beta) != 0.f) {
                    tval = (beta - alpha) / beta;
                    invden = 1.f / (alpha - beta);
                } else { tval = 0.f; invden = 0.f; beta = alpha; }
                sval[0] = beta; sval[1] = tval; sval[2] = invden;
            }
            __syncthreads();
            float beta = sval[0], tval = sval[1], invden = sval[2];

            for (int r = tid; r < n; r += TPB) {
                float vv;
                if (r < k) vv = 0.f;
                else if (r == k) vv = 1.f;
                else vv = colk[r] * invden;
                vcol[r] = vv;
            }
            __syncthreads();

            for (int j = k + 1 + tid; j < n; j += TPB) {
                float* Acol = Acmb + (size_t)j * n;
                float w = 0.f;
                for (int r = k; r < n; ++r) w += vcol[r] * Acol[r];
                float tw = tval * w;
                for (int r = k; r < n; ++r) Acol[r] -= tw * vcol[r];
            }
            __syncthreads();

            for (int r = tid; r < n; r += TPB) {
                if (r == k) colk[r] = beta;
                else if (r > k) colk[r] = vcol[r];
            }
            if (tid == 0) taub[k] = tval;
            __syncthreads();
        }
        if (tid == 0) taub[n - 1] = 0.f;
        __syncthreads();

        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            Hb[r * n + c] = Acmb[c * n + r];
        }
        __syncthreads();
    }
}

void qr_global_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr,
                      int64_t tau_ptr, int B, int n, int grid) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    size_t shbytes = ((size_t)TPB + n + 4) * sizeof(float);
    qr_global_kernel<TPB><<<grid, TPB, shbytes>>>(A, Acm, H, tau, B, n);
}

// ===========================================================================
// Blocked compact-WY Householder QR, ONE BLOCK PER MATRIX. The active column
// panel lives in shared memory; the trailing block is updated with a
// BLAS-3 (I - V T^T V^T) sweep that reuses V and a trailing chunk from smem.
// Matrix held in a column-major global scratch (Acm[b*n*n + c*n + r]); H is
// written row-major in geqrf packing.
//
// NB  = panel width (reflectors per block step)
// CT  = trailing-column chunk width processed per smem tile
// ===========================================================================
template <int TPB, int NB, int CT>
__global__ void qr_blocked_kernel(const float* __restrict__ A,
                                  float* __restrict__ Acm,
                                  float* __restrict__ H,
                                  float* __restrict__ tau,
                                  int B, int n) {
    extern __shared__ float smem[];
    float* Ps   = smem;                 // n * NB  : current panel (col-major)
    float* Ts   = Ps + (size_t)n * NB;  // NB * NB : T (col-major: Ts[i + l*NB])
    float* Cs   = Ts + NB * NB;         // n * CT  : trailing chunk (col-major)
    float* Ws   = Cs + (size_t)n * CT;  // 2*NB*CT : W and W' workspace
    float* taus = Ws + 2 * NB * CT;     // NB      : panel tau values
    float* red  = taus + NB;            // REDSZ   : reductions / warp partials
    const int REDSZ = (8 * NB > TPB) ? 8 * NB : TPB;
    float* pww  = red + REDSZ;          // NB      : panel-update w (tau*w) values
    float* sval = pww + NB;             // scalars

    const int tid = threadIdx.x;

    for (int b = blockIdx.x; b < B; b += gridDim.x) {
        const float* Ab = A + (size_t)b * n * n;
        float* Acmb = Acm + (size_t)b * n * n;
        float* Hb = H + (size_t)b * n * n;
        float* taub = tau + (size_t)b * n;

        // row-major -> column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Acmb[c * n + r] = Ab[r * n + c];
        }
        __syncthreads();

        for (int p = 0; p < n; p += NB) {
            int nb = NB; if (p + nb > n) nb = n - p;

            // ---- load panel Acm[:, p:p+nb] into Ps (full height) ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Ps[(size_t)j * n + r] = Acmb[(size_t)(p + j) * n + r];
            }
            __syncthreads();

            // ---- panel factorization (unblocked, in smem) ----
            for (int j = 0; j < nb; ++j) {
                int c = p + j;
                float* pj = Ps + (size_t)j * n;       // panel column j
                // norm over rows >= c
                float partial = 0.f;
                for (int r = c + tid; r < n; r += TPB) {
                    float x = pj[r]; partial += x * x;
                }
                red[tid] = partial; __syncthreads();
                for (int s = TPB / 2; s > 0; s >>= 1) {
                    if (tid < s) red[tid] += red[tid + s];
                    __syncthreads();
                }
                if (tid == 0) {
                    float xnorm = sqrtf(red[0]);
                    float alpha = pj[c];
                    float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                    float tval, invden;
                    if (xnorm > 0.f && (alpha - beta) != 0.f) {
                        tval = (beta - alpha) / beta;
                        invden = 1.f / (alpha - beta);
                    } else { tval = 0.f; invden = 0.f; beta = alpha; }
                    sval[0] = beta; sval[1] = tval; sval[2] = invden;
                }
                __syncthreads();
                float beta = sval[0], tval = sval[1], invden = sval[2];
                // normalize reflector for rows r>c (scale by invden); leave
                // rows r<c (R values) untouched; row c set to 1 transiently for
                // the panel update, restored to beta afterwards.
                for (int r = c + 1 + tid; r < n; r += TPB) pj[r] = pj[r] * invden;
                __syncthreads();
                if (tid == 0) { pj[c] = 1.f; taus[j] = tval; }
                __syncthreads();
                // apply reflector to ALL remaining panel columns jj>j at once.
                // Batched: each thread accumulates partial dots for every jj in
                // registers over its row strip (one pass), warp-reduces, then a
                // single block sync produces w[jj]; finally update all columns.
                // This collapses (nb-j) block reductions into ~2 syncs.
                int ntrail = nb - (j + 1);
                if (ntrail > 0) {
                    const int lane = tid & 31;
                    const int warp = tid >> 5;
                    const int NWARP = TPB / 32;
                    float pw[NB];
                    #pragma unroll
                    for (int t = 0; t < NB; ++t) pw[t] = 0.f;
                    for (int r = c + tid; r < n; r += TPB) {
                        float vr = pj[r];
                        for (int t = 0; t < ntrail; ++t)
                            pw[t] += vr * Ps[(size_t)(j + 1 + t) * n + r];
                    }
                    // warp-reduce each pw[t]; warp leaders -> red[warp*NB + t]
                    for (int t = 0; t < ntrail; ++t) {
                        float v = pw[t];
                        #pragma unroll
                        for (int o = 16; o > 0; o >>= 1)
                            v += __shfl_down_sync(0xffffffff, v, o);
                        if (lane == 0) red[warp * NB + t] = v;
                    }
                    __syncthreads();
                    // thread t sums NWARP warp-partials -> tau*w[t] in pww
                    if (tid < ntrail) {
                        float w = 0.f;
                        for (int wi = 0; wi < NWARP; ++wi) w += red[wi * NB + tid];
                        pww[tid] = tval * w;  // tau*w
                    }
                    __syncthreads();
                    // update all trailing panel columns
                    for (int t = 0; t < ntrail; ++t) {
                        float tw = pww[t];
                        float* pjj = Ps + (size_t)(j + 1 + t) * n;
                        for (int r = c + tid; r < n; r += TPB)
                            pjj[r] -= tw * pj[r];
                    }
                    __syncthreads();
                }
                // store beta (R diagonal) back into panel column j at row c
                if (tid == 0) pj[c] = beta;
                __syncthreads();
            }
            // restore implicit unit diagonal of V for the WY math: we need
            // V with V[c,j]=1. Currently pj[c]=beta. Use a separate read:
            // build T using V where diag=1. We'll treat Ps diag specially.

            // ---- build T (compact WY) ----
            // V[r,i] = (r==p+i)?1 : (r>p+i? Ps[i*n+r] : 0).  beta sits on diag
            // in Ps so we must override it to 1 when used as V.
            // T[i,i]=taus[i]; for l>i: T[i,l] = -taus[l]*sum_{m<=l-1}... use
            // column recurrence: for each l, z[i]=V[:,i]^T V[:,l] (i<l), then
            // T[0:l,l] = -taus[l]* T[0:l,0:l] @ z.
            // init diagonal
            for (int i = tid; i < nb; i += TPB) Ts[(size_t)i + (size_t)i * NB] = taus[i];
            __syncthreads();
            for (int l = 1; l < nb; ++l) {
                int cl = p + l;
                // z[i] = V[:,i]^T V[:,l] for all i<l, computed in ONE fused pass
                // (rows r>=cl, with V[cl,l]=1): each thread accumulates partial
                // z[i] for every i in registers, warp-shuffle reduce, 1 sync.
                // Replaces l block-reductions with ~2 syncs.
                const float* Vl = Ps + (size_t)l * n;
                const int lane = tid & 31, warp = tid >> 5;
                const int NWARP = TPB / 32;
                float pz[NB];
                #pragma unroll
                for (int t = 0; t < NB; ++t) pz[t] = 0.f;
                for (int r = cl + tid; r < n; r += TPB) {
                    float vl = (r == cl) ? 1.f : Vl[r];
                    for (int i = 0; i < l; ++i)
                        pz[i] += Ps[(size_t)i * n + r] * vl;
                }
                for (int i = 0; i < l; ++i) {
                    float v = pz[i];
                    #pragma unroll
                    for (int o = 16; o > 0; o >>= 1)
                        v += __shfl_down_sync(0xffffffff, v, o);
                    if (lane == 0) red[warp * NB + i] = v;
                }
                __syncthreads();
                // thread i sums NWARP warp-partials -> z[i] in Ws[i]
                if (tid < l) {
                    float zz = 0.f;
                    for (int wi = 0; wi < NWARP; ++wi) zz += red[wi * NB + tid];
                    Ws[tid] = zz;
                }
                __syncthreads();
                // T[0:l,l] = -taus[l] * (T[0:l,0:l] @ z)
                float tl = taus[l];
                for (int i = tid; i < l; i += TPB) {
                    float acc = 0.f;
                    for (int m = i; m < l; ++m)  // T upper-tri: T[i,m], m>=i
                        acc += Ts[(size_t)i + (size_t)m * NB] * Ws[m];
                    Ts[(size_t)i + (size_t)l * NB] = -tl * acc;
                }
                __syncthreads();
            }

            // ---- trailing update: cols [p+nb, n) in chunks of CT ----
            int tstart = p + nb;
            for (int g0 = tstart; g0 < n; g0 += CT) {
                int ct = CT; if (g0 + ct > n) ct = n - g0;
                // load chunk Acm[:, g0:g0+ct] into Cs
                for (int idx = tid; idx < n * ct; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Cs[(size_t)g * n + r] = Acmb[(size_t)(g0 + g) * n + r];
                }
                __syncthreads();
                // W[i,g] = sum_{r>=p} V[r,i] * Cs[r,g]   (i<nb, g<ct).  G-tile by
                // 2: one i, two adjacent g -> load V[r,i] once, reuse across the
                // two chunk columns (halves the Vi smem traffic). Diagonal term
                // V[ci,i]=1 handled separately.
                int ng2 = (ct + 1) / 2;
                for (int idx = tid; idx < nb * ng2; idx += TPB) {
                    int gt = idx / nb, i = idx % nb;
                    int g0 = gt * 2;
                    bool hg1 = (g0 + 1 < ct);
                    int ci = p + i;
                    const float* Vi = Ps + (size_t)i * n;
                    const float* C0 = Cs + (size_t)g0 * n;
                    const float* C1 = Cs + (size_t)(g0 + 1) * n;
                    float s0 = C0[ci];                 // V[ci,i]=1 term
                    float s1 = hg1 ? C1[ci] : 0.f;
                    float t0 = 0.f, t1 = 0.f;
                    int r = ci + 1;
                    for (; r + 1 < n; r += 2) {
                        float v0 = Vi[r], v1 = Vi[r + 1];
                        s0 += v0 * C0[r];     t0 += v1 * C0[r + 1];
                        if (hg1) { s1 += v0 * C1[r]; t1 += v1 * C1[r + 1]; }
                    }
                    for (; r < n; ++r) {
                        float v0 = Vi[r];
                        s0 += v0 * C0[r];
                        if (hg1) s1 += v0 * C1[r];
                    }
                    Ws[(size_t)i + (size_t)g0 * NB] = s0 + t0;
                    if (hg1) Ws[(size_t)i + (size_t)(g0 + 1) * NB] = s1 + t1;
                }
                __syncthreads();
                // W' = T^T @ W :  W'[i,g] = sum_{l<=i} T[l,i] W[l,g]
                // do in place using a temp per (i,g): read all W[l,g] l<=i
                // Store into Cs-free? Need separate buffer; reuse red? Instead
                // compute into registers by reading Ws then overwrite Ws after
                // a barrier. Use a second pass writing to taus? Too small.
                // Allocate W' in the same Ws by computing top-down is unsafe.
                // Simplest: compute W'[i,g] reading Ws (old), write to Cs top
                // rows? No. Use a small stack array since nb<=NB known const.
                {
                    // each thread handles some (i,g); reads Ws[l,g] for l<=i.
                    // Ws is read-only here; we write results to a shadow in
                    // the unused tail of Cs? Cs is n*CT, we only use n rows.
                    // Use Ts is busy. We'll write W' into Ps? Ps is V, busy.
                    // Allocate via local then sync-store: two-phase.
                }
                // Two-phase T^T W using register temp + barrier:
                // phase 1: each (i,g) computes wp into a per-thread value and
                // stashes into red is too small. Instead loop g-chunks small:
                // We compute W' in place safely because W'[i] depends on W[l<=i]
                // -> process i from high to low won't help (needs lower l).
                // Use a separate smem region: extend Ws to 2*NB*CT.
                for (int idx = tid; idx < nb * ct; idx += TPB) {
                    int g = idx / nb, i = idx % nb;
                    float acc = 0.f;
                    for (int l = 0; l <= i; ++l)
                        acc += Ts[(size_t)l + (size_t)i * NB] * Ws[(size_t)l + (size_t)g * NB];
                    // stash in second half
                    Ws[(size_t)NB * CT + (size_t)i + (size_t)g * NB] = acc;
                }
                __syncthreads();
                // Cs[r,g] -= sum_i V[r,i] * W'[i,g]   (r>=p).  Register-tile
                // over g (4 cols/thread): load V[r,i] once, reuse across the
                // g-tile -> 4x fewer strided Ps[i*n+r] loads.
                const float* Wp = Ws + (size_t)NB * CT;
                int nrows = n - p;          // active rows r in [p, n)
                int ng4 = (ct + 3) / 4;     // number of g-tiles of width 4
                for (int idx = tid; idx < nrows * ng4; idx += TPB) {
                    int gt = idx / nrows;
                    int rr = idx % nrows;
                    int r = p + rr;
                    int g0c = gt * 4;
                    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
                    bool h1 = (g0c + 1 < ct), h2 = (g0c + 2 < ct), h3 = (g0c + 3 < ct);
                    for (int i = 0; i < nb; ++i) {
                        int ci = p + i;
                        if (r < ci) break;
                        float vi = (r == ci) ? 1.f : Ps[(size_t)i * n + r];
                        const float* Wpi = Wp + i;
                        acc0 += vi * Wpi[(size_t)(g0c) * NB];
                        if (h1) acc1 += vi * Wpi[(size_t)(g0c + 1) * NB];
                        if (h2) acc2 += vi * Wpi[(size_t)(g0c + 2) * NB];
                        if (h3) acc3 += vi * Wpi[(size_t)(g0c + 3) * NB];
                    }
                    Cs[(size_t)(g0c) * n + r] -= acc0;
                    if (h1) Cs[(size_t)(g0c + 1) * n + r] -= acc1;
                    if (h2) Cs[(size_t)(g0c + 2) * n + r] -= acc2;
                    if (h3) Cs[(size_t)(g0c + 3) * n + r] -= acc3;
                }
                __syncthreads();
                // write chunk back to global
                for (int idx = tid; idx < n * ct; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Acmb[(size_t)(g0 + g) * n + r] = Cs[(size_t)g * n + r];
                }
                __syncthreads();
            }

            // ---- write panel back to global scratch (R + reflectors) ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Acmb[(size_t)(p + j) * n + r] = Ps[(size_t)j * n + r];
            }
            // store tau for this panel
            for (int j = tid; j < nb; j += TPB) taub[p + j] = taus[j];
            __syncthreads();
        }
        if (tid == 0) { /* last tau handled per-panel */ }

        // write H row-major from column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Hb[r * n + c] = Acmb[c * n + r];
        }
        __syncthreads();
    }
}

template <int TPB, int NB, int CT>
static void launch_blocked(const float* A, float* Acm, float* H, float* tau,
                           int B, int n, int grid) {
    const int REDSZ = (8 * NB > TPB) ? 8 * NB : TPB;
    size_t fcount = (size_t)n * NB + NB * NB + (size_t)n * CT
                    + 2 * NB * CT + NB + REDSZ + NB + 8;
    size_t shbytes = fcount * sizeof(float);
    cudaFuncSetAttribute(qr_blocked_kernel<TPB, NB, CT>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)shbytes);
    qr_blocked_kernel<TPB, NB, CT><<<grid, TPB, shbytes>>>(A, Acm, H, tau, B, n);
}

void qr_blocked_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr,
                       int64_t tau_ptr, int B, int n, int grid, int cfg) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    switch (cfg) {
        case 0: launch_blocked<TPB, 32, 64>(A, Acm, H, tau, B, n, grid); break;
        case 1: launch_blocked<TPB, 48, 48>(A, Acm, H, tau, B, n, grid); break;
        case 2: launch_blocked<TPB, 64, 32>(A, Acm, H, tau, B, n, grid); break;
        case 3: launch_blocked<TPB, 64, 24>(A, Acm, H, tau, B, n, grid); break;
        case 4: launch_blocked<TPB, 32, 96>(A, Acm, H, tau, B, n, grid); break;
        case 5: launch_blocked<TPB, 16, 128>(A, Acm, H, tau, B, n, grid); break;
        case 6: launch_blocked<TPB, 16, 32>(A, Acm, H, tau, B, n, grid); break;
        case 7: launch_blocked<TPB, 16, 16>(A, Acm, H, tau, B, n, grid); break;
        case 8: launch_blocked<TPB, 24, 24>(A, Acm, H, tau, B, n, grid); break;
        case 9: launch_blocked<TPB, 16, 64>(A, Acm, H, tau, B, n, grid); break;
        case 10: launch_blocked<TPB, 8, 64>(A, Acm, H, tau, B, n, grid); break;
        case 11: launch_blocked<TPB, 16, 48>(A, Acm, H, tau, B, n, grid); break;
        default: launch_blocked<TPB, 32, 64>(A, Acm, H, tau, B, n, grid); break;
    }
}
"""

_CUDA_CPP = r"""
#include <cstdint>
#include <torch/extension.h>

void qr_smem_launch(int64_t A_ptr, int64_t H_ptr, int64_t tau_ptr,
                    int B, int n, int grid);
void qr_global_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr,
                      int64_t tau_ptr, int B, int n, int grid);
void qr_blocked_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr,
                       int64_t tau_ptr, int B, int n, int grid, int cfg);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("qr_smem_launch", &qr_smem_launch, "QR smem launch");
    m.def("qr_global_launch", &qr_global_launch, "QR global launch");
    m.def("qr_blocked_launch", &qr_blocked_launch, "QR blocked WY launch");
}
"""

_qr_cuda_mod = None


def _get_cuda_mod():
    global _qr_cuda_mod
    if _qr_cuda_mod is None:
        import os
        import hashlib
        from torch.utils.cpp_extension import load
        ext_dir = os.environ.get("TORCH_EXTENSIONS_DIR", "/tmp/qr_ext")
        h = hashlib.md5((_CUDA_SRC + _CUDA_CPP).encode()).hexdigest()[:8]
        bdir = os.path.join(ext_dir, f"qr_smem_v1_{h}")
        os.makedirs(bdir, exist_ok=True)
        cu_path = os.path.join(bdir, "qr_kernel.cu")
        cpp_path = os.path.join(bdir, "qr_bind.cpp")
        with open(cu_path, "w") as f:
            f.write(_CUDA_SRC)
        with open(cpp_path, "w") as f:
            f.write(_CUDA_CPP)
        _qr_cuda_mod = load(
            name="qr_smem_v1",
            sources=[cpp_path, cu_path],
            extra_cuda_cflags=["-O3", "--use_fast_math"],
            build_directory=bdir,
            verbose=False,
        )
    return _qr_cuda_mod


def _qr_cuda_smem(a: torch.Tensor) -> output_t:
    B, n, _ = a.shape
    H = torch.empty_like(a)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    num_sms = torch.cuda.get_device_properties(a.device).multi_processor_count
    grid = min(num_sms * 2, B)
    if grid < 1:
        grid = 1
    _get_cuda_mod().qr_smem_launch(
        a.data_ptr(), H.data_ptr(), tau.data_ptr(), B, n, grid)
    return H, tau


def _qr_cuda_global(a: torch.Tensor) -> output_t:
    B, n, _ = a.shape
    H = torch.empty_like(a)
    Acm = torch.empty_like(a)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    num_sms = torch.cuda.get_device_properties(a.device).multi_processor_count
    grid = min(num_sms, B)
    if grid < 1:
        grid = 1
    _get_cuda_mod().qr_global_launch(
        a.data_ptr(), Acm.data_ptr(), H.data_ptr(), tau.data_ptr(), B, n, grid)
    return H, tau


# cfg index -> (NB, CT). Must mirror the C++ switch in qr_blocked_launch.
_BLOCKED_CFG = {
    0: (32, 64), 1: (48, 48), 2: (64, 32), 3: (64, 24), 4: (32, 96),
    5: (16, 128), 6: (16, 32), 7: (16, 16), 8: (24, 24), 9: (16, 64),
    10: (8, 64), 11: (16, 48),
}


def _blocked_smem_bytes(n: int, cfg: int) -> int:
    NB, CT = _BLOCKED_CFG.get(cfg, (32, 64))
    TPB = 256
    redsz = max(8 * NB, TPB)
    fcount = n * NB + NB * NB + n * CT + 2 * NB * CT + NB + redsz + NB + 8
    return fcount * 4


def _qr_cuda_blocked(a: torch.Tensor, cfg: int = 0) -> output_t:
    B, n, _ = a.shape
    props = torch.cuda.get_device_properties(a.device)
    # Defensive: if the chosen config exceeds this device's smem opt-in budget,
    # fall back to the reference path rather than launch-fail into garbage.
    smem_cap = getattr(props, "shared_memory_per_block_optin", 0) or 227000
    if _blocked_smem_bytes(n, cfg) > smem_cap:
        return torch.geqrf(a)
    H = torch.empty_like(a)
    Acm = torch.empty_like(a)
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    num_sms = props.multi_processor_count
    grid = min(num_sms, B)
    if grid < 1:
        grid = 1
    _get_cuda_mod().qr_blocked_launch(
        a.data_ptr(), Acm.data_ptr(), H.data_ptr(), tau.data_ptr(),
        B, n, grid, cfg)
    return H, tau


# Max n for which n*n + slack floats fit in 227KB smem.
# (227328 - (256+256+4)*4) / 4 ~= 56300 -> n <= 237. Use 224 for headroom.
_SMEM_MAX_N = 224

# Compile the CUDA extension eagerly at import so build-time surfaces errors.
_get_cuda_mod()


def custom_kernel(data: input_t) -> output_t:
    a = data
    n = a.shape[-1]
    if n <= 64:
        return _qr_triton(a.contiguous())
    # The blocked compact-WY megakernel (batched panel/T-build reductions)
    # beats the full-matrix-in-smem kernel even at small n that fits smem,
    # so route everything n=65..1024 through it.
    if n <= 384:
        return _qr_cuda_blocked(a.contiguous(), 5)  # NB16 CT128
    if n <= 512:
        return _qr_cuda_blocked(a.contiguous(), 11)  # NB16 CT48
    if n <= 1024:
        return _qr_cuda_blocked(a.contiguous(), 8)  # NB24 CT24
    return torch.geqrf(a)

