#include <cstdio>
#include <cuda_runtime.h>

template<int TPB>
__global__ void probe_kernel(float* x) {
    extern __shared__ float s[];
    int t = threadIdx.x;
    float acc = 0.f;
    for (int i=0;i<8;i++) acc += s[t+i*TPB];
    x[blockIdx.x*TPB+t] = acc;
}

int main(){
    cudaDeviceProp p; cudaGetDeviceProperties(&p, 0);
    printf("SMs=%d smemPerSM=%zu smemPerBlockOptin=%zu regsPerBlock=%d maxThreadsPerSM=%d\n",
           p.multiProcessorCount, p.sharedMemPerMultiprocessor, p.sharedMemPerBlockOptin,
           p.regsPerBlock, p.maxThreadsPerMultiProcessor);
    // test occupancy for TPB=256 with various smem
    for (int smemKB : {0, 8, 16, 32, 48, 64}) {
        int blocks;
        cudaFuncSetAttribute(probe_kernel<256>, cudaFuncAttributeMaxDynamicSharedMemorySize, smemKB*1024);
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, probe_kernel<256>, 256, smemKB*1024);
        printf("TPB=256 smem=%dKB -> %d blocks/SM -> grid=%d\n", smemKB, blocks, blocks*p.multiProcessorCount);
    }
    for (int smemKB : {0, 8, 16, 32}) {
