        // scale reflector rows r>c by invden, set v[c]=1 transiently
        for (int r = c + 1 + tid; r < n; r += TPB) colc[r] *= invden;
        __syncthreads();
        if (tid == 0) { colc[c] = 1.f; taub[c] = tval; }
        __syncthreads();
        // apply reflector j to remaining panel cols jj>j (batched dots)
        int ntrail = nb - (j + 1);
        if (ntrail > 0) {
            float pw[NBMAX];
            #pragma unroll
            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
            for (int r = c + tid; r < n; r += TPB) {
                float vr = colc[r];
                for (int t = 0; t < ntrail; ++t)
                    pw[t] += vr * Acm[(size_t)(c + 1 + t) * n + r];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[warp * 1 + t * NWARP] = v;  // pack [t][warp]
            }
            __syncthreads();
            if (tid < ntrail) {
                float w = 0.f;
                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
                zsh[tid] = tval * w;
            }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* cjj = Acm + (size_t)(c + 1 + t) * n;
                for (int r = c + tid; r < n; r += TPB) cjj[r] -= tw * colc[r];
            }
            __syncthreads();
        }
        if (tid == 0) colc[c] = beta;   // store R diagonal
        __syncthreads();
    }
    // ---- build T (compact WY), Tg col-major: Tg[i + l*NBMAX] ----
    for (int i = tid; i < nb; i += TPB) Tg[(size_t)i + (size_t)i * NBMAX] = taub[p + i];
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        int cl = p + l;
        const float* Vl = Acm + (size_t)cl * n;   // V column l (diag is beta, treat as 1)
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int r = cl + tid; r < n; r += TPB) {
            float vl = (r == cl) ? 1.f : Vl[r];
            for (int i = 0; i < l; ++i) {
                const float* Vi = Acm + (size_t)(p + i) * n;
                float vi = (r == p + i) ? 1.f : Vi[r];
                pz[i] += vi * vl;
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taub[p + l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
}

// Apply block reflector to a slab of trailing columns. Every CTA runs this and
// grid-strides over trailing columns. Each thread owns whole trailing columns.
// C[:,g] -= V (T^T (V^T C[:,g])),  V = Acm[:, p:p+nb] (unit diag), rows >= p.
template <int TPB, int NBMAX>
__device__ void coop_trailing_update(float* __restrict__ Acm, const float* __restrict__ Tg,
                                     int n, int p, int nb) {
    const int tid = threadIdx.x;
    const int gtid = blockIdx.x * TPB + tid;
    const int gstride = gridDim.x * TPB;
    int tstart = p + nb;
    // Cache T (nb x nb upper-tri, col-major) in smem -- tiny, broadcast.
    __shared__ float Ts[NBMAX * NBMAX];
    for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
    // (note NBMAX layout: Tg[i + l*NBMAX]; we repack contiguously into Ts[i+l*nb])
    __syncthreads();

    for (int g = tstart + gtid; g < n; g += gstride) {
        float* Cg = Acm + (size_t)g * n;
        float w[NBMAX];
        // w[i] = sum_{r>=p+i} V[r,i] * C[r,g]   (V[p+i,i]=1)
        for (int i = 0; i < nb; ++i) {
            int ci = p + i;
            const float* Vi = Acm + (size_t)ci * n;
            float acc = Cg[ci];                 // V[ci,i]=1 term
            for (int r = ci + 1; r < n; ++r) acc += Vi[r] * Cg[r];
            w[i] = acc;
        }
        // wp = T^T w :  wp[i] = sum_{l<=i} T[l,i] * w[l]
        float wp[NBMAX];
        for (int i = 0; i < nb; ++i) {
            float acc = 0.f;
            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * w[l];
            wp[i] = acc;
        }
        // C[r,g] -= sum_i V[r,i] * wp[i]   (r >= p, V[p+i,i]=1, V[r,i]=0 for r<p+i)
        for (int r = p; r < n; ++r) {
            float acc = 0.f;
            int imax = r - p; if (imax >= nb) imax = nb - 1;
            for (int i = 0; i <= imax; ++i) {
                int ci = p + i;
                float vi = (r == ci) ? 1.f : Acm[(size_t)ci * n + r];
                acc += vi * wp[i];
            }
            Cg[r] -= acc;
        }
    }
}

template <int TPB, int NBMAX>
__global__ void qr_coop_kernel(const float* __restrict__ A, float* __restrict__ Acm,
                               float* __restrict__ H, float* __restrict__ tau,
                               float* __restrict__ Tg, unsigned int* __restrict__ g_bar,
                               int n, int NB, int gridSize) {
    const int tid = threadIdx.x;
    const int gtid = blockIdx.x * TPB + tid;
    const int gstride = gridDim.x * TPB;
    unsigned int sense = 0u;

    // row-major A -> column-major Acm (all CTAs)
    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
        int r = idx / n, c = idx % n;
        Acm[(size_t)c * n + r] = A[(size_t)r * n + c];
    }
    coop_grid_barrier(g_bar, gridSize, sense);

    for (int p = 0; p < n; p += NB) {
        int nb = NB; if (p + nb > n) nb = n - p;
        if (blockIdx.x == 0) coop_panel_factor<TPB, NBMAX>(Acm, Tg, tau, n, p, nb);
        coop_grid_barrier(g_bar, gridSize, sense);
        coop_trailing_update<TPB, NBMAX>(Acm, Tg, n, p, nb);
        coop_grid_barrier(g_bar, gridSize, sense);
    }

    // column-major Acm -> row-major H (all CTAs)
    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
        int r = idx / n, c = idx % n;
        H[(size_t)r * n + c] = Acm[(size_t)c * n + r];
    }
}

template <int TPB, int NBMAX>
static int coop_max_grid(int NB) {
    int blocks = 0;
    size_t sh = (size_t)NBMAX * NBMAX * sizeof(float);  // Ts in trailing update
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_coop_kernel<TPB, NBMAX>, TPB, sh);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    return blocks * sms;
}

void qr_coop_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
                    int64_t Tg_ptr, int64_t gbar_ptr, int n, int NB, int gridcap) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    unsigned int* g_bar = reinterpret_cast<unsigned int*>(gbar_ptr);
    const int TPB = 256;
    const int NBMAX = 64;
    int maxg = coop_max_grid<TPB, NBMAX>(NB);
    int grid = maxg; if (gridcap > 0 && gridcap < grid) grid = gridcap;
    size_t sh = (size_t)NBMAX * NBMAX * sizeof(float);
    qr_coop_kernel<TPB, NBMAX><<<grid, TPB, sh>>>(A, Acm, H, tau, Tg, g_bar, n, NB, grid);
}
