// Apply block reflector to the trailing submatrix. Every CTA grid-strides over
// COLUMN TILES of width CT; within a tile it does the WY update as two row-tiled
// GEMMs (V streamed through smem in row strips of RB):
//   pass 1:  W  = V^T C          (W is nb x CT, accumulated across strips)
//            W' = T^T W
//   pass 2:  C -= V W'
// V = Acm[:, p:p+nb] (implicit unit diag, V[p+i,i]=1, zero above), rows >= p.
// CT trailing columns of C stay in global (read once in pass 1, read+written in
// pass 2). T (nb x nb upper-tri) and W/W' (nb x CT) live in smem.
template <int TPB, int NBMAX, int CT, int RB>
__device__ void coop_trailing_update(float* __restrict__ Acm, const float* __restrict__ Tg,
                                     int n, int p, int nb) {
    const int tid = threadIdx.x;
    __shared__ float Ts[NBMAX * NBMAX];      // T (col-major contiguous: Ts[l + i*nb])
    __shared__ float Ws[NBMAX * CT];         // W / W'  (col-major: Ws[i + g*nb])
    __shared__ float Vs[RB * NBMAX];         // V row strip (col-major: Vs[rr + i*RB])
    // cache T
    for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
    __syncthreads();

    const int tstart = p + nb;
    for (int g0 = tstart + blockIdx.x * CT; g0 < n; g0 += gridDim.x * CT) {
        int ct = CT; if (g0 + ct > n) ct = n - g0;

        // ---- pass 1: W[i,g] = sum_{r>=p} V[r,i] C[r,g] ----
        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
        __syncthreads();
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            // load V strip Vs[rr, i] = V[r0+rr, i]  (unit diag, zero above diag)
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            // each thread owns (i,g) pairs; accumulate over the strip's rows.
            for (int idx = tid; idx < nb * ct; idx += TPB) {
                int g = idx / nb, i = idx % nb;
                const float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cg[r0 + rr];
                Ws[i + g * nb] += acc;
            }
            __syncthreads();
        }
        // ---- W' = T^T W :  W'[i,g] = sum_{l<=i} T[l,i] W[l,g]  (in place ok? no) ----
        // compute into registers then write back after a barrier.
        for (int idx = tid; idx < nb * ct; idx += TPB) {
            int g = idx / nb, i = idx % nb;
            float acc = 0.f;
            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
            // stash via second pass: reuse Vs region is unsafe; use a temp reg + sync
            Ws[i + g * nb] = -acc;   // negate so pass2 does C += V*Ws  (=> C -= V W')
            // NOTE: this is a WAR hazard-free overwrite only because each thread
            // writes its own (i,g) AFTER reading all l<=i of the SAME column g,
            // and l<=i means we only read entries at or below i in column g, which
            // for ascending i could already be overwritten. Fix with double buffer.
        }
        __syncthreads();
        // ---- pass 2: C[r,g] += V[r,i] * Ws[i,g]  (Ws already negated) ----
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            for (int idx = tid; idx < rb * ct; idx += TPB) {
                int g = idx / rb, rr = idx % rb, r = r0 + rr;
                float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                int imax = r - p; if (imax >= nb) imax = nb - 1;
                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Ws[i + g * nb];
                Cg[r] += acc;
            }
            __syncthreads();
        }
    }
}

