721	// Factor + build-T for one panel, executed by BLOCK 0 only. BLAS-2 over global
722	// column-major Acm. NBMAX bounds the per-thread register arrays.
723	template <int TPB, int NBMAX>
724	__device__ void coop_panel_factor(float* __restrict__ Acm, float* __restrict__ Tg,
725	                                  float* __restrict__ taub, int n, int p, int nb) {
726	    const int NWARP_C = TPB / 32;
727	    const int REDSZ = (NBMAX * NWARP_C > TPB) ? NBMAX * NWARP_C : TPB;
728	    __shared__ float red[REDSZ];
729	    __shared__ float sval[4];
730	    __shared__ float zsh[NBMAX];
731	    const int tid = threadIdx.x;
732	    const int lane = tid & 31, warp = tid >> 5, NWARP = TPB / 32;
733	
734	    for (int j = 0; j < nb; ++j) {
735	        int c = p + j;
736	        float* colc = Acm + (size_t)c * n;        // panel column j (global)
