// Factor + build-T for one panel, executed by BLOCK 0 only. BLAS-2 over global
// column-major Acm. NBMAX bounds the per-thread register arrays.
template <int TPB, int NBMAX>
__device__ void coop_panel_factor(float* __restrict__ Acm, float* __restrict__ Tg,
                                  float* __restrict__ taub, int n, int p, int nb) {
    const int NWARP_C = TPB / 32;
    const int REDSZ = (NBMAX * NWARP_C > TPB) ? NBMAX * NWARP_C : TPB;
    __shared__ float red[REDSZ];
    __shared__ float sval[4];
    __shared__ float zsh[NBMAX];
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5, NWARP = TPB / 32;

    for (int j = 0; j < nb; ++j) {
        int c = p + j;
        float* colc = Acm + (size_t)c * n;        // panel column j (global)
        // --- column norm over rows >= c ---
        float partial = 0.f;
        for (int r = c + tid; r < n; r += TPB) { float x = colc[r]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = colc[c];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) {
                tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta);
            } else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        // scale reflector rows r>c by invden, set v[c]=1 transiently
        for (int r = c + 1 + tid; r < n; r += TPB) colc[r] *= invden;
        __syncthreads();
        if (tid == 0) { colc[c] = 1.f; taub[c] = tval; }
        __syncthreads();
        // apply reflector j to remaining panel cols jj>j (batched dots)
        int ntrail = nb - (j + 1);
        if (ntrail > 0) {
            float pw[NBMAX];
            #pragma unroll
            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
            for (int r = c + tid; r < n; r += TPB) {
                float vr = colc[r];
                for (int t = 0; t < ntrail; ++t)
                    pw[t] += vr * Acm[(size_t)(c + 1 + t) * n + r];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;  // pack [t][warp]
            }
            __syncthreads();
            if (tid < ntrail) {
                float w = 0.f;
                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
                zsh[tid] = tval * w;
            }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* cjj = Acm + (size_t)(c + 1 + t) * n;
                for (int r = c + tid; r < n; r += TPB) cjj[r] -= tw * colc[r];
            }
            __syncthreads();
        }
        if (tid == 0) colc[c] = beta;   // store R diagonal
        __syncthreads();
    }
    // ---- build T (compact WY), Tg col-major: Tg[i + l*NBMAX] ----
    for (int i = tid; i < nb; i += TPB) Tg[(size_t)i + (size_t)i * NBMAX] = taub[p + i];
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        int cl = p + l;
        const float* Vl = Acm + (size_t)cl * n;   // V column l (diag is beta, treat as 1)
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int r = cl + tid; r < n; r += TPB) {
            float vl = (r == cl) ? 1.f : Vl[r];
            for (int i = 0; i < l; ++i) {
                const float* Vi = Acm + (size_t)(p + i) * n;
                float vi = (r == p + i) ? 1.f : Vi[r];
                pz[i] += vi * vl;
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taub[p + l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
}

