// Factor + build-T for one panel, executed by BLOCK 0 only. The ACTIVE sub-panel
// (rows [p,n) x nb columns) is loaded into shared memory and factored ON-CHIP
// (the single-block-over-global panel was the dominant bottleneck); reflectors +
// R diag are written back to global Acm. T (compact WY) is built in smem and
// written to Tg. dsmem layout: Ps[(r-p) + j*ldp] holds the sub-panel, ldp=n-p.
template <int TPB, int NBMAX>
__device__ void coop_panel_factor(float* __restrict__ Acm, float* __restrict__ Tg,
                                  float* __restrict__ taub, float* dsmem,
                                  int n, int p, int nb) {
    const int NWARP = TPB / 32;
    const int REDSZ = (NBMAX * NWARP > TPB) ? NBMAX * NWARP : TPB;
    __shared__ float red[REDSZ];
    __shared__ float sval[4];
    __shared__ float zsh[NBMAX];
    __shared__ float taus[NBMAX];
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    const int ldp = n - p;                 // sub-panel leading dimension (rows)
    float* Ps = dsmem;                     // ldp * nb  (col-major: Ps[rr + j*ldp])

    // load active sub-panel rows [p,n) of cols [p,p+nb) into smem
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Ps[rr + j * ldp] = Acm[(size_t)(p + j) * n + (p + rr)];
    }
    __syncthreads();

    for (int j = 0; j < nb; ++j) {
        float* pj = Ps + (size_t)j * ldp;  // panel column j (smem); local row rj=j
        int rj = j;                        // diagonal local row for this column
        // --- column norm over local rows >= rj ---
        float partial = 0.f;
        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = pj[rj];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) {
                tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta);
            } else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = nb - (j + 1);
        if (ntrail > 0) {
            float pw[NBMAX];
            #pragma unroll
            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t)
                    pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;
            }
            __syncthreads();
            if (tid < ntrail) {
                float w = 0.f;
                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
                zsh[tid] = tval * w;
            }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
            }
            __syncthreads();
        }
        if (tid == 0) pj[rj] = beta;       // R diagonal
        __syncthreads();
    }
    // ---- build T (compact WY) from smem panel, Tg col-major Tg[i + l*NBMAX] ----
    for (int i = tid; i < nb; i += TPB) { Tg[(size_t)i + (size_t)i * NBMAX] = taus[i]; taub[p + i] = taus[i]; }
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        const float* Vl = Ps + (size_t)l * ldp;     // V column l (local diag row l = beta -> treat as 1)
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int rr = l + tid; rr < ldp; rr += TPB) {
            float vl = (rr == l) ? 1.f : Vl[rr];
            for (int i = 0; i < l; ++i) {
                const float* Vi = Ps + (size_t)i * ldp;
                float vi = (rr == i) ? 1.f : Vi[rr];
                pz[i] += vi * vl;
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taus[l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
    // ---- write factored sub-panel back to global Acm (rows [p,n), cols [p,p+nb)) ----
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Acm[(size_t)(p + j) * n + (p + rr)] = Ps[rr + j * ldp];
    }
    __syncthreads();
}

