template <int NBMAX, int CT, int RB>
static size_t coop_smem_bytes(int n) {
    // dynamic smem must cover BOTH the panel sub-panel (rows[p,n) x NBMAX, max at
    // p=0 -> n*NBMAX) and the trailing-update buffers.
    size_t panel = (size_t)n * NBMAX;
    size_t trail = (size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT + (size_t)RB * NBMAX;
    size_t fcount = panel > trail ? panel : trail;
    return fcount * sizeof(float);
}

template <int TPB, int NBMAX, int CT, int RB>
static int coop_max_grid(size_t sh) {
    int blocks = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_coop_kernel<TPB, NBMAX, CT, RB>, TPB, sh);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    return blocks * sms;
}

template <int TPB, int NBMAX, int CT, int RB>
static void coop_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
                          unsigned int* g_bar, int n, int gridcap) {
    size_t sh = coop_smem_bytes<NBMAX, CT, RB>(n);
    cudaFuncSetAttribute(qr_coop_kernel<TPB, NBMAX, CT, RB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)sh);
    int maxg = coop_max_grid<TPB, NBMAX, CT, RB>(sh);
    int grid = maxg; if (gridcap > 0 && gridcap < grid) grid = gridcap;
    if (grid < 1) grid = 1;
    qr_coop_kernel<TPB, NBMAX, CT, RB><<<grid, TPB, sh>>>(A, Acm, H, tau, Tg, g_bar, n, grid);
}

void qr_coop_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
                    int64_t Tg_ptr, int64_t gbar_ptr, int n, int NB, int gridcap) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    unsigned int* g_bar = reinterpret_cast<unsigned int*>(gbar_ptr);
    const int TPB = 256;
    const int CT = 32;       // trailing column-tile width per CTA
    const int RB = 64;       // V row-strip height streamed through smem
    switch (NB) {
        case 8:  coop_dispatch<TPB, 8,  CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        case 16: coop_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        case 24: coop_dispatch<TPB, 24, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        case 32: coop_dispatch<TPB, 32, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        default: coop_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
    }
}

